import test from 'node:test';import assert from 'node:assert/strict';import {followupDigest} from '../../reda-2/followup-digest.mjs';
const plan={id:'p',version:2,payload:{exercises:[{id:'e',name:'Benspark'}]}};const now='2026-09-19T08:00:00Z';
test('digest condenses sessions and exercise friction without claiming clinical outcome',()=>{const d=followupDigest({plan,now,sessions:[{plan_id:'p',plan_version:2,status:'completed',started_at:'2026-09-18T08:00:00Z',payload:{exercises:[{exerciseId:'e',status:'completed',feedback:'heavy'}]}}]});assert.equal(d.completed,1);assert.match(d.headline,/1 genomförda pass/);assert.equal(d.flags[0].label,'Benspark');assert.equal(d.action,'Granska underlaget')});
test('patient request and worse response surface as separate facts',()=>{const d=followupDigest({plan,now,responses:[{plan_id:'p',plan_version:2,created_at:'2026-09-18T10:00:00Z',answers:{nextDay:'worse',contact:'yes'}}]});assert.deepEqual(d.flags.slice(0,2).map(x=>x.kind),['symptoms','contact'])});
test('old and foreign plan evidence is excluded',()=>{const d=followupDigest({plan,now,sessions:[{plan_id:'other',plan_version:2,status:'completed',started_at:'2026-09-18T08:00:00Z'},{plan_id:'p',plan_version:2,status:'completed',started_at:'2026-08-01T08:00:00Z'}]});assert.equal(d.sessionCount,0)});
test('absence of flags is phrased as absence in registered evidence, not recovery',()=>{const d=followupDigest({plan,now});assert.match(d.action,/registrerat underlag/);assert.doesNotMatch(d.action,/bra|återhämt|progress/)});
